    const idx = db.benachrichtigungen.findIndex((x) => x.gelesen);
    db.benachrichtigungen.splice(idx >= 0 ? idx : 0, 1);
  }
  const einstellung = { ...mailEinstellungenStandard(), ...(u.mailEinstellungen || {}) };
