    verifiziertAm: f.verifiziertAm || null,
    naechstePruefung: f.naechstePruefung || null,
    ausweisGueltigBis: f.person?.ausweis?.gueltigBis || null,
    ausweisTage: tageBis(f.person?.ausweis?.gueltigBis),
