/** Vertrag: Backoffice oder Eigentümer (fremd → 403) */
export async function pachtvertrag(n, id) {
  angemeldet(n);
  const db = await lesenBereit();
  const p = db.finanzen.pachtvertraege.find((x) => x.id === v.kennung(id));
