const B = "http://localhost:3100";
async function login(email) {
  const r = await fetch(B + "/api/auth/login", { method: "POST", headers: { "Content-Type": "application/json", Origin: B }, body: JSON.stringify({ email, passwort: "Demo-2026!" }) });
  const c = (r.headers.getSetCookie?.() || []).map((x) => x.split(";")[0]).find((x) => /oi_sitzung=/.test(x));
  if (!c) throw new Error("login " + r.status + " " + (await r.text()).slice(0, 200));
