  const t0 = Date.now();
  const r = await fetch(B + p, { headers: { Cookie: c } });
  const txt = await r.text();
  console.log(p, r.status, `${Date.now() - t0} ms`);
  try { return JSON.parse(txt); } catch { console.log(txt.slice(0, 600)); return null; }
