    uid: g.uid || g.uidNummer || "", firmenbuch: [g.firmenbuch || g.registernummer || g.fn, g.gericht].filter(Boolean).join(", "),
    iban: g.iban || bank.iban || "", bic: g.bic || bank.bic || "", beispielIban: false, erpnextCompany: g.erpnextCompany || g.company || g.name || "", spv: true, bekannt: !!g.id,
  };
}

