}

/** Alle bekannten Gesellschaften (ÖkoInvest GmbH + Verzeichnis) */
export function gesellschaftenListe(db) {
  return [gesellschaftFuer(db, OEKOINVEST_ID), ...verzeichnis(db).filter((g) => g?.id).map((g) => gesellschaftFuer(db, g.id))];
}

