def _verzeichnis_eintrag(gid):
	"""Gesellschaftsverzeichnis (Team A2) – tolerant: DocType „Plattform Gesellschaft“ mit üblichen Feldnamen."""
	for dt in ("Plattform Gesellschaft", "Plattform Gesellschaften"):
		if frappe.db.exists("DocType", dt) and frappe.db.exists(dt, gid):
			return frappe.get_doc(dt, gid).as_dict()
