 * Nur wenn das KYC-Modul in dieser Demo-Datenbank (noch) keine Daten hat, gelten die Demo-Stammdaten db.finanzen.kycDemo.
 */
export function kycAuszahlung(db, { kontoId, organisationId = null, flaecheId = null }) {
  if (db.kyc) {
