    return { quelle: "kyc", aktiv: fr.aktiv !== false, status: fr.status, verifiziert: fr.status === "verifiziert", ok: gruende.length === 0, gruende, iban: bank.iban || "", bic: bank.bic || "", kontoinhaber: bank.kontoinhaber || "" };
